// Code Generated by AI: AI helped adapt the Assignment 3 script to load JSON,
// handle loading errors, and format arrival dates with Day.js.

import dayjs from "dayjs";

// The animal data is loaded from the JSON file instead of being hardcoded here.
let animals = [];

let activeFilter = "all";
let activeSort = "default";

// Create and display an individual animal card.
function displayAnimals(animalArray) {
  const animalList = document.querySelector("#animal-list");
  animalList.innerHTML = "";

  if (animalArray.length === 0) {
    animalList.textContent = "No animals match your selection.";
    return;
  }

  animalArray.forEach(function (animal) {
    const card = document.createElement("article");
    card.classList.add("animal-card");

    if (animal.adopted) {
      card.classList.add("adopted");
    }

    const name = document.createElement("h3");
    name.textContent = animal.name;

    const species = document.createElement("p");
    species.textContent = `Species: ${animal.species}`;

    const age = document.createElement("p");
    age.textContent = `Age: ${animal.age}`;

    card.append(name, species, age);

    // Show the breed when the JSON record provides one.
    if (animal.breed) {
      const breed = document.createElement("p");
      breed.textContent = `Breed: ${animal.breed}`;
      card.appendChild(breed);
    }

    const status = document.createElement("p");
    status.classList.add("animal-status");
    status.textContent = animal.adopted ? "Adopted" : "Available";
    card.appendChild(status);

    // Day.js formats the arrival date and calculates whole days since arrival.
    if (animal.intakeDate) {
      const arrivalDate = document.createElement("p");
      const parsedDate = dayjs(animal.intakeDate);

      if (parsedDate.isValid()) {
        const formattedDate = parsedDate.format("MMM D, YYYY");
        const daysAtShelter = Math.max(
          0,
          dayjs().startOf("day").diff(parsedDate.startOf("day"), "day")
        );

        arrivalDate.textContent =
          `Arrived ${formattedDate} (${daysAtShelter} days ago)`;
      } else {
        arrivalDate.textContent = "Arrival date unavailable";
      }

      card.appendChild(arrivalDate);
    }

    const button = document.createElement("button");
    button.type = "button";
    button.classList.add("adoption-button");
    button.textContent = animal.adopted ? "Return to Available" : "Adopt";

    // The callback uses the animal's id to update the correct record.
    button.addEventListener("click", function () {
      toggleAdoption(animal.id);
    });

    card.appendChild(button);
    animalList.appendChild(card);
  });
}

// Change an animal's adoption status and refresh the board.
function toggleAdoption(animalId) {
  const animal = animals.find(function (item) {
    return item.id === animalId;
  });

  if (!animal) {
    return;
  }

  animal.adopted = !animal.adopted;
  updateDisplay();
}

// Filter and sort a copy of the loaded data.
function updateDisplay() {
  let displayedAnimals = animals.slice();

  if (activeFilter === "available") {
    displayedAnimals = displayedAnimals.filter(function (animal) {
      return animal.adopted === false;
    });
  } else if (activeFilter === "adopted") {
    displayedAnimals = displayedAnimals.filter(function (animal) {
      return animal.adopted === true;
    });
  }

  if (activeSort === "name") {
    displayedAnimals.sort(function (a, b) {
      return a.name.localeCompare(b.name);
    });
  } else if (activeSort === "age") {
    displayedAnimals.sort(function (a, b) {
      return a.age - b.age;
    });
  }

  displayAnimals(displayedAnimals);
  updateCount(displayedAnimals.length);
}

// Show the number of available animals and how many are currently displayed.
function updateCount(displayedCount) {
  const countElement = document.querySelector("#animal-count");

  const availableCount = animals.filter(function (animal) {
    return animal.adopted === false;
  }).length;

  countElement.textContent =
    `${availableCount} of ${animals.length} animals are available. ` +
    `Showing ${displayedCount} animal(s).`;
}

// Filter buttons.
document.querySelector("#show-all").addEventListener("click", function () {
  activeFilter = "all";
  updateDisplay();
});

document.querySelector("#show-available").addEventListener("click", function () {
  activeFilter = "available";
  updateDisplay();
});

document.querySelector("#show-adopted").addEventListener("click", function () {
  activeFilter = "adopted";
  updateDisplay();
});

// Sorting dropdown.
document.querySelector("#sort-animals").addEventListener("change", function (event) {
  activeSort = event.target.value;
  updateDisplay();
});

// Load animal records from the public JSON file.
async function loadAnimals() {
  const countElement = document.querySelector("#animal-count");
  const animalList = document.querySelector("#animal-list");

  countElement.textContent = "Loading animals...";
  animalList.innerHTML = "";

  try {
    // BASE_URL includes the repository path on GitHub Pages.
    const response = await fetch(
      `${import.meta.env.BASE_URL}animals.json`
    );

    // fetch() does not automatically throw for HTTP errors such as a 404.
    // response.ok must be checked to catch unsuccessful HTTP status codes.
    if (!response.ok) {
      throw new Error(`Request failed with status ${response.status}`);
    }

    // await waits for the JSON response to be parsed without blocking the page.
    animals = await response.json();

    updateDisplay();
  } catch (error) {
    console.error("Unable to load animals:", error);

    countElement.textContent = "Unable to load animals.";

    const errorMessage = document.createElement("p");
    errorMessage.classList.add("error-message");
    errorMessage.textContent =
      "Sorry, the animals could not be loaded. Check your connection and refresh the page.";

    animalList.innerHTML = "";
    animalList.appendChild(errorMessage);
  }
}

loadAnimals();
